-- Seed mock vehicles and customers for development/demo
-- Run after 00004_seed_demo_org.sql

-- Ensure demo org exists
DO $$
begin
  if not exists (select 1 from public.organizations where slug = 'khantaishir-motors') then
    insert into public.organizations (id, name, slug, settings, is_active)
    values (
      '00000000-0000-0000-0000-000000000001',
      'хантайшир моторс',
      'khantaishir-motors',
      '{}'::jsonb,
      true
    );
  end if;
end $$;

